func LookupPort(name string) (int, bool) {
    raw, ok := config[name]        // ok == false means absent
    if !ok {
        return 0, false
    }
    port, err := strconv.Atoi(raw) // failure travels as the second value
    return port, err == nil
}

if port, ok := LookupPort("http"); ok {
    listen(port)
}
